/* Loop #9 C verification harness: curve25519-sha256@libssh.org KEX core.
 *
 * Verifies the MoonBit implementation (src/kexc25519/) against OpenSSH's
 * ORIGINAL C code on vectors generated by kex_c25519_python_ref.py:
 *
 *   - crypto_scalarmult_curve25519: real smult_curve25519_ref.c (OpenSSH)
 *   - mpint encoding: REAL sshbuf_put_bignum2_bytes (sshbuf.c + getput-basic)
 *   - exchange hash input assembly: transcribed field-by-field from
 *     kexgen.c:48-96 (static fn; annotated) over the same REAL sshbuf
 *   - SHA-256: BSD sha2.c (same as Loops #5/#6)
 *   - KDF derive_key: transcribed from kex.c:1069-1118 (annotated)
 *
 * Expected values are COMPUTED by python cryptography - never hand-copied.
 */
#include <stdio.h>
#include "kex_c25519_compat.h"
#include "sha2_stub.h"
#include "bsd-sha2.h"

/* NOTE: kex_sshbuf.h is intentionally NOT included here first - it must be
 * entered from kex_sshbuf.c with SSHBUF_INTERNAL defined, otherwise the
 * _SSHBUF_H include guard swallows the internal section on re-inclusion. */

/* OpenSSH originals pulled into this single TU */
#include "smult_curve25519_ref.c"          /* djb ref scalarmult ($OpenBSD) */
#include "kex_sshbuf.c"                     /* sshbuf core ($OpenBSD) */
#include "kex_sshbuf_getput_basic.c"        /* incl. put_bignum2_bytes ($OpenBSD) */
#include "sha2.c"                           /* BSD SHA-256 ($OpenBSD) */

/* sshbuf_find lives in sshbuf-misc.c which drags in socket headers;
 * the harness never calls the only consumer (get_nulterminated_string),
 * so provide a link-satisfying stub marked unreachable. */
int sshbuf_find(const struct sshbuf *b, size_t start_offset,
    const void *s, size_t len, size_t *offsetp);
int sshbuf_find(const struct sshbuf *b, size_t start_offset,
    const void *s, size_t len, size_t *offsetp)
{
    (void)b; (void)start_offset; (void)s; (void)len; (void)offsetp;
    fprintf(stderr, "FATAL: sshbuf_find stub called\n");
    exit(3);
    return -1;
}

#define CURVE25519_SIZE 32

static int g_fails = 0;

/* ---------------- hex helpers ---------------- */

static size_t hex_decode(const char *hex, unsigned char *out, size_t outsz)
{
    size_t n = strlen(hex) / 2, i;
    if (n > outsz) exit(2);
    for (i = 0; i < n; i++) {
        char c1 = hex[2 * i], c2 = hex[2 * i + 1];
        int hi = (c1 >= '0' && c1 <= '9') ? c1 - '0' :
                 (c1 >= 'a' && c1 <= 'f') ? c1 - 'a' + 10 :
                 (c1 >= 'A' && c1 <= 'F') ? c1 - 'A' + 10 : -1;
        int lo = (c2 >= '0' && c2 <= '9') ? c2 - '0' :
                 (c2 >= 'a' && c2 <= 'f') ? c2 - 'a' + 10 :
                 (c2 >= 'A' && c2 <= 'F') ? c2 - 'A' + 10 : -1;
        if (hi < 0 || lo < 0) { fprintf(stderr, "BAD HEX\n"); exit(2); }
        out[i] = (unsigned char)((hi << 4) | lo);
    }
    return n;
}

static void check_hex(const char *label, const unsigned char *got,
                      size_t gotlen, const char *want_hex)
{
    unsigned char want[8192];
    size_t wantlen = hex_decode(want_hex, want, sizeof(want));
    if (gotlen != wantlen) {
        printf("FAIL %-34s len %lu != %lu\n", label,
               (unsigned long)gotlen, (unsigned long)wantlen);
        g_fails++;
        return;
    }
    if (memcmp(got, want, wantlen) != 0) {
        size_t i;
        for (i = 0; i < wantlen; i++)
            if (got[i] != want[i]) break;
        printf("FAIL %-34s byte %lu: %02x != %02x\n", label,
               (unsigned long)i, got[i], want[i]);
        g_fails++;
        return;
    }
    printf("PASS %s\n", label);
}

static void check_cond(const char *label, int ok)
{
    if (!ok) { printf("FAIL %s\n", label); g_fails++; }
    else printf("PASS %s\n", label);
}

