/* ---------------- SHA-256 wrapper ---------------- */

static void sha256_buf(const struct sshbuf *in, unsigned char out[32])
{
    SHA2_CTX ctx;
    SHA256Init(&ctx);
    SHA256Update(&ctx, sshbuf_ptr((struct sshbuf *)in), sshbuf_len(in));
    SHA256Final(out, &ctx);
}

/* ---------------- kex_gen_hash (transcribed from kexgen.c:48-96) ---
 * Field order is the single source of truth for this layer:
 * string(V_C)||string(V_S)|| u32(|I_C|+1)||u8(20)||I_C ||
 * u32(|I_S|+1)||u8(20)||I_S ||string(KS)||string(e)||string(f)|| K_raw
 * ------------------------------------------------------------------ */
static void kex_gen_hash_c(const unsigned char *vc, size_t vclen,
                           const unsigned char *vs, size_t vslen,
                           const unsigned char *ic, size_t iclen,
                           const unsigned char *is_, size_t islen,
                           const unsigned char *ks, size_t kslen,
                           const unsigned char *e, size_t elen,
                           const unsigned char *f, size_t flen,
                           const unsigned char *ss_mpint, size_t sslen,
                           unsigned char hash[32])
{
    struct sshbuf *b = sshbuf_new();
    if (b == NULL) exit(2);
    /* sshbuf_put_stringb equivalents: length-prefixed copies */
    sshbuf_put_string(b, vc, vclen);
    sshbuf_put_string(b, vs, vslen);
    /* fake header: len covers the type byte (+1), type=SSH2_MSG_KEXINIT=20 */
    sshbuf_put_u32(b, (u_int)(iclen + 1));
    sshbuf_put_u8(b, 20);
    sshbuf_put(b, ic, iclen);
    sshbuf_put_u32(b, (u_int)(islen + 1));
    sshbuf_put_u8(b, 20);
    sshbuf_put(b, is_, islen);
    sshbuf_put_string(b, ks, kslen);
    sshbuf_put_string(b, e, elen);
    sshbuf_put_string(b, f, flen);
    sshbuf_put(b, ss_mpint, sslen);   /* raw append of encoded K */
    sha256_buf(b, hash);
    sshbuf_free(b);
}

/* ---------------- derive_key (transcribed from kex.c:1069-1118) ----
 * K1 = HASH(K||H||letter||session_id)
 * Kn = HASH(K||H||K1..Kn-1)      <- no session_id in expansion
 * ------------------------------------------------------------------ */
static void derive_key_c(unsigned char letter, size_t need,
                         const unsigned char *hash, size_t hashlen,
                         const unsigned char *ss_mpint, size_t sslen,
                         const unsigned char *session_id, size_t sidlen,
                         unsigned char *out)
{
    SHA2_CTX ctx;
    unsigned char digest[4096];
    size_t have, mdsz = 32;
    size_t cap = ((need + mdsz - 1) / mdsz) * mdsz;

    /* K1 */
    {
        struct sshbuf *b = sshbuf_new();
        sshbuf_put(b, ss_mpint, sslen);
        sshbuf_put(b, hash, hashlen);
        sshbuf_put_u8(b, letter);
        sshbuf_put(b, session_id, sidlen);
        sha256_buf(b, digest);
        sshbuf_free(b);
    }
    have = mdsz;
    while (have < need) {
        struct sshbuf *b = sshbuf_new();
        if (have + mdsz > sizeof(digest) || have > cap) exit(2);
        sshbuf_put(b, ss_mpint, sslen);
        sshbuf_put(b, hash, hashlen);
        sshbuf_put(b, digest, have);
        sha256_buf(b, digest + have);
        sshbuf_free(b);
        have += mdsz;
    }
    memcpy(out, digest, need);
}

int main(void)
{
    unsigned char alice_sk[32], alice_pk[32], bob_pk[32];
    unsigned char ss[32], pk_out[32], zero_pub[32];
    unsigned char vc[64], vs[64], ic[512], is_[512], ks[256];
    unsigned char e[32], f[32], ss_mpint[64], hash[32];
    unsigned char keys[6][64];

    printf("=== Loop #9 harness: OpenSSH original C vs python/MoonBit ===\n");

    hex_decode(ALICE_SK, alice_sk, sizeof(alice_sk));
    hex_decode(ALICE_PK, alice_pk, sizeof(alice_pk));
    hex_decode(BOB_PK, bob_pk, sizeof(bob_pk));

    printf("--- Section A: scalarmult + mpint ---\n");
    /* keygen: pub = X25519(sk, basepoint9) via REAL OpenSSH ref code */
    {
        unsigned char bp[CURVE25519_SIZE];
        memset(bp, 0, sizeof(bp));
        bp[0] = 9;
        check_cond("C/keygen rv",
                   crypto_scalarmult_curve25519(pk_out, alice_sk, bp) == 0);
        check_hex("C/A1 keygen e ", pk_out, 32, ALICE_PK);
    }
    /* shared secret both directions */
    check_cond("C/ss alice->bob rv",
               crypto_scalarmult_curve25519(ss, alice_sk, bob_pk) == 0);
    check_hex("C/A1 ss raw   ", ss, 32, SS_RAW);

    /* mpint via REAL sshbuf_put_bignum2_bytes: no-prepend branch */
    {
        struct sshbuf *buf = sshbuf_new();
        sshbuf_put_bignum2_bytes(buf, ss, 32);
        check_hex("C/A1 ss mpint ", sshbuf_ptr(buf), sshbuf_len(buf), SS_MPINT);
        sshbuf_free(buf);
    }
    /* prepend branch */
    {
        unsigned char sk2[32], ss2[32];
        struct sshbuf *buf;
        hex_decode(A2_SK, sk2, sizeof(sk2));
        check_cond("C/A2 rv",
                   crypto_scalarmult_curve25519(ss2, sk2, alice_pk) == 0);
        check_hex("C/A2 ss raw   ", ss2, 32, A2_SS);
        buf = sshbuf_new();
        sshbuf_put_bignum2_bytes(buf, ss2, 32);
        check_hex("C/A2 ss mpint ", sshbuf_ptr(buf), sshbuf_len(buf), A2_MPINT);
        sshbuf_free(buf);
    }
    /* all-zero rejection: X25519(sk, zero_pub) must be all-zero here */
    {
        unsigned char z[32];
        memset(zero_pub, 0, sizeof(zero_pub));
        check_cond("C/A3 zero rv",
                   crypto_scalarmult_curve25519(z, alice_sk, zero_pub) == 0);
        {
            int all_zero = 1, i;
            for (i = 0; i < 32; i++)
                if (z[i] != 0) { all_zero = 0; break; }
            check_cond("C/A3 zero ss -> REJECT path", all_zero);
        }
    }

    printf("--- Section B: exchange hash + KDF ---\n");
    {
        size_t vclen = hex_decode(B_VC, vc, sizeof(vc));
        size_t vslen = hex_decode(B_VS, vs, sizeof(vs));
        size_t iclen = hex_decode(B_IC, ic, sizeof(ic));
        size_t islen = hex_decode(B_IS, is_, sizeof(is_));
        size_t kslen = hex_decode(B_KS_BLOB, ks, sizeof(ks));
        size_t sslen = hex_decode(SS_MPINT, ss_mpint, sizeof(ss_mpint));
        memcpy(e, alice_pk, 32);
        memcpy(f, bob_pk, 32);

        kex_gen_hash_c(vc, vclen, vs, vslen, ic, iclen, is_, islen,
                       ks, kslen, e, 32, f, 32, ss_mpint, sslen, hash);
        check_hex("C/B H         ", hash, 32, B_H);

        /* six keys, we_need=64, letters A..F */
        {
            static const char *labels[6] =
                { "iv_ctos", "iv_stoc", "enc_ctos",
                  "enc_stoc", "mac_ctos", "mac_stoc" };
            static const char *wants[6] =
                { B_IV_CTOS, B_IV_STOC, B_ENC_CTOS,
                  B_ENC_STOC, B_MAC_CTOS, B_MAC_STOC };
            int i;
            for (i = 0; i < 6; i++) {
                char label[96];
                derive_key_c('A' + i, 64, hash, 32, ss_mpint, sslen,
                             hash, 32, keys[i]);
                snprintf(label, sizeof(label), "C/B key %s", labels[i]);
                check_hex(label, keys[i], 64, wants[i]);
            }
        }
    }

    printf("=== %s (fails=%d) ===\n",
           g_fails == 0 ? "ALL PASS" : "FAILED", g_fails);
    return g_fails == 0 ? 0 : 1;
}
